// Shared wallet/contract setup for all pages.
// contractAddress and contractABI come from config.js (generated by deploy.js),
// so config.js must be included before this file.
let web3;
let account;
let wishlistContract;

async function init() {
    if (!window.ethereum) {
        console.error("Ethereum provider not detected.");
        alert('MetaMask is not installed!');
        return false;
    }

    web3 = new Web3(window.ethereum);
    try {
        const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' });
        account = accounts[0];
        console.log("Connected account:", account);

        wishlistContract = new web3.eth.Contract(contractABI, contractAddress);
        console.log("Wishlist contract initialized successfully");

        setupEventListeners(); // Вызов после инициализации контракта

        await updateAccountInfo();
        return true;
    } catch (error) {
        console.error("Error connecting to MetaMask:", error);
        return false;
    }
}

async function updateAccountInfo() {
    if (!account) {
        console.error("No account connected.");
        return;
    }

    const balanceWei = await web3.eth.getBalance(account);
    const balanceEther = web3.utils.fromWei(balanceWei, "ether");
    console.log(`Account balance: ${balanceEther} ETH`);
    document.getElementById("user-address").textContent = shortAddress(account);
    document.getElementById("user-balance").textContent = `${balanceEther} ETH`;
}

function shortAddress(address) {
    return address.slice(0, 6) + '...' + address.slice(-4);
}

// **Отслеживание событий контракта**
function setupEventListeners() {
    // Subscriptions need a websocket provider; MetaMask may not support them, so failures are only logged
    try {
        wishlistContract.events.WishCreated({ fromBlock: "latest" })
            .on("data", event => console.log("Wish Created:", event.returnValues))
            .on("error", console.error);

        wishlistContract.events.WishFunded({ fromBlock: "latest" })
            .on("data", event => console.log("Wish Funded:", event.returnValues))
            .on("error", console.error);

        wishlistContract.events.WishClosed({ fromBlock: "latest" })
            .on("data", event => console.log("Wish Closed:", event.returnValues))
            .on("error", console.error);
    } catch (error) {
        console.warn("Event subscriptions are not available:", error);
    }
}

// **Инициализация** — pages wait for this promise before using the contract
const walletReady = init();
